// AvgustovStory 1.2.0: hearts are earned by cooking and lost by dying (quest "Гурман" in the Kitchen chapter).
// Data per food item comes from avgustov_kitchen_data.js (generated by tools/kitchen_gen.js): AV_KD[id] = [tier, groups].
//
// Gourmet points (user, 20.11.2026): every new dish (food restoring 4+ hunger points) gives points by complexity:
// 1 simple (furnace, campfire, 1-2 ingredients), 2 prepared (cutting board, 3-4 ingredients), 3 fine (cooking pot,
// Create machines, kegs, winery, feasts). Hearts: start 8, +1 at each of AV_KD_MILESTONES (10 ... 360 points), max 20.
// A Crystal Heart (Legendary Survival Overhaul item; 9 fragments) gives +1 heart on right click.
// A death takes 1 heart, never below 8; the heart comes back for as many points of different dishes (known ones count)
// as the last stage took, or with a Crystal Heart.
// Model: hearts = 8 + stages + delta, stages = max(stages by points, m_floor). m_floor keeps the hearts earned under
// the old dish-count rules (migration kd_v 2), so nobody loses a heart. delta (Crystal Hearts minus deaths) is kept
// inside [-stages, 12 - stages].
// Feasts (servings taken from a feast block) count for every member of the eater's guild within 16 blocks.
// Diet: the groups of the last 10 meals and drinks (meat/fish/eggs/cheese, vegetables/fruit, bread/grain, sweet,
// drinks): 3 groups -> Haste I, 4 -> also Strength I, all 5 -> also Resistance I (10 min, refreshed by every meal).
// 10 meals in a row from one group -> "Однообразно": Weakness I for 5 min. The same dish 8 times in a row -> "Приелось":
// Hunger for 20 s, and that meal does not count.
// Ranks at stages 1, 3, 5, 7, 9, 11, 12 are announced to everyone and pay Numismatics coins.
// /hearts shows the progress, /gourmet gives (or refreshes) the "Журнал гурмана" book.
// State: server persistent data by player UUID, av_kitchen/<uuid> = tasted dishes, av_hearts/<uuid> = the rest.
const AV_KITCHEN_OLD_MILESTONES = [5, 10, 20, 30, 45, 60, 80, 100, 125, 150, 180, 210];
const AV_KITCHEN_MIN_NUTRITION = 4;
const AV_HEARTS_START = 8, AV_HEARTS_MAX = 20;
const AV_DIET_LEN = 10, AV_BORED = 8, AV_FEAST_RANGE = 16;
const AV_GROUPS = [
  { bit: 1, name: 'мясо, рыба, яйца' }, { bit: 2, name: 'овощи и фрукты' }, { bit: 4, name: 'хлеб и злаки' },
  { bit: 8, name: 'сладкое' }, { bit: 16, name: 'напитки' }];
const AV_RANKS = [
  { stage: 1, name: 'Поварёнок', reward: 'numismatics:bevel 2' }, { stage: 3, name: 'Кашевар', reward: 'numismatics:cog 1' },
  { stage: 5, name: 'Повар', reward: 'numismatics:cog 2' }, { stage: 7, name: 'Повар артели', reward: 'numismatics:cog 4' },
  { stage: 9, name: 'Шеф-повар', reward: 'numismatics:crown 1' }, { stage: 11, name: 'Гурман', reward: 'numismatics:crown 2' },
  { stage: 12, name: 'Легенда кухни', reward: 'numismatics:crown 4' }];
const AV_DataComponents = Java.loadClass('net.minecraft.core.component.DataComponents');
const AV_KH_CompoundTag = Java.loadClass('net.minecraft.nbt.CompoundTag');

function avKitchenSub(server, name, id) {
  var root = server.persistentData;
  if (!root.contains(name)) root.put(name, new AV_KH_CompoundTag());
  var store = root.getCompound(name);
  if (!store.contains(id)) store.put(id, new AV_KH_CompoundTag());
  return store.getCompound(id);
}
function avKitchenPlayer(server, player) { return avKitchenSub(server, 'av_kitchen', String(player.uuid)); }
function avHeartState(server, player) { return avKitchenSub(server, 'av_hearts', String(player.uuid)); }
function avDishTier(key) { var d = AV_KD[key]; return d ? (d[0] || 0) : 1; }
function avDishGroups(key) { var d = AV_KD[key]; return d ? (d[1] || 0) : 0; }
function avStars(t) { return t >= 3 ? '★★★' : t == 2 ? '★★' : '★'; }
function avPointsOf(tag) {
  var p = 0, it = tag.getAllKeys().iterator();
  while (it.hasNext()) p += Math.max(1, avDishTier(String(it.next())));
  return p;
}
function avStagesBy(points) {
  var h = 0;
  AV_KD_MILESTONES.forEach(function (m) { if (points >= m) h++; });
  return h;
}
function avNextMilestone(points) {
  for (var i = 0; i < AV_KD_MILESTONES.length; i++) if (AV_KD_MILESTONES[i] > points) return AV_KD_MILESTONES[i];
  return null;
}
// Points and the old-rules floor are refreshed once per login (migration to kd_v 2 on the first one).
function avKitchenSync(server, player) {
  var st = avHeartState(server, player), tasted = avKitchenPlayer(server, player);
  if (st.getInt('kd_v') < 2) {
    var n = tasted.getAllKeys().size(), old = 0;
    AV_KITCHEN_OLD_MILESTONES.forEach(function (m) { if (n >= m) old++; });
    st.putInt('m_floor', old);
    st.putInt('kd_v', 2);
    st.putInt('rec_need', 0); // the debt is counted in points from now on
  }
  st.putInt('pts', avPointsOf(tasted));
  return st;
}
function avStages(server, player) {
  var st = avHeartState(server, player);
  return Math.max(avStagesBy(st.getInt('pts')), st.getInt('m_floor'));
}
// Returns the player's hearts after clamping delta into its allowed range.
function avHearts(server, player) {
  var m = avStages(server, player);
  var st = avHeartState(server, player);
  var d = st.getInt('delta');
  var lo = -m, hi = AV_HEARTS_MAX - AV_HEARTS_START - m;
  if (d < lo) d = lo;
  if (d > hi) d = hi;
  st.putInt('delta', d);
  return AV_HEARTS_START + m + d;
}
function avHeartsApply(server, player) {
  var n = player.username;
  var h = avHearts(server, player);
  server.runCommandSilent('attribute ' + n + ' minecraft:generic.max_health modifier remove avgustov:kitchen_hearts');
  if (h !== 10) server.runCommandSilent('attribute ' + n + ' minecraft:generic.max_health modifier add avgustov:kitchen_hearts ' + ((h - 10) * 2) + ' add_value');
  server.runCommandSilent('scoreboard players set ' + n + ' av_hearts ' + h);
  return h;
}
function avHeartsTitle(server, n, title, color, sub) {
  server.runCommandSilent('title ' + n + ' times 10 60 20');
  server.runCommandSilent('title ' + n + ' subtitle ' + JSON.stringify({ text: sub, color: 'gray', italic: true }));
  server.runCommandSilent('title ' + n + ' title ' + JSON.stringify({ text: title, color: color, bold: true }));
}
function avRankOf(stages) {
  var r = null;
  AV_RANKS.forEach(function (x) { if (stages >= x.stage) r = x; });
  return r;
}
// Announces ranks the player has newly reached (once each) and pays their reward.
function avRankCheck(server, player) {
  var st = avHeartState(server, player), stages = avStages(server, player), n = player.username;
  AV_RANKS.forEach(function (x, i) {
    if (stages < x.stage || st.getInt('rank') > i) return;
    st.putInt('rank', i + 1);
    server.runCommandSilent('give ' + n + ' ' + x.reward);
    server.runCommandSilent('tellraw @a ' + JSON.stringify([{ text: n, color: 'yellow' }, { text: ' получает кухонное звание ', color: 'gold' },
      { text: '«' + x.name + '»', color: 'yellow', bold: true }, { text: '.', color: 'gold' }]));
  });
}

// Diet over the last meals; returns the action bar part and applies the effects.
function avDiet(s, player, key, groups, isFood) {
  var n = player.username;
  var st = avHeartState(s, player);
  if (isFood) {
    var streak = String(st.getString('streak_item')) === key ? st.getInt('streak') + 1 : 1;
    st.putString('streak_item', key);
    st.putInt('streak', streak);
    if (streak >= AV_BORED) {
      s.runCommandSilent('effect give ' + n + ' minecraft:hunger 20 0');
      return [{ text: 'Приелось: ', color: 'red' }, { text: streak + '-й раз подряд одно и то же — поешьте что-нибудь другое', color: 'gray' }];
    }
  }
  var raw = String(st.getString('diet'));
  var list = raw ? raw.split(',') : [];
  list.push(String(groups));
  while (list.length > AV_DIET_LEN) list.shift();
  st.putString('diet', list.join(','));
  var union = 0, same = list.length >= AV_DIET_LEN, first = parseInt(list[0]) || 0;
  list.forEach(function (g) { var v = parseInt(g) || 0; union |= v; if (v !== first) same = false; });
  var count = 0;
  AV_GROUPS.forEach(function (g) { if (union & g.bit) count++; });
  if (count >= 3) s.runCommandSilent('effect give ' + n + ' minecraft:haste 600 0 true');
  if (count >= 4) s.runCommandSilent('effect give ' + n + ' minecraft:strength 600 0 true');
  if (count >= 5) s.runCommandSilent('effect give ' + n + ' minecraft:resistance 600 0 true');
  if (same && count <= 1) {
    s.runCommandSilent('effect give ' + n + ' minecraft:weakness 300 0');
    return [{ text: 'Однообразно: ', color: 'red' }, { text: '10 раз подряд одна группа еды — Слабость. Нужен рацион пошире.', color: 'gray' }];
  }
  var bonus = count >= 5 ? 'Спешка, Сила, Сопротивление' : count >= 4 ? 'Спешка и Сила · 5 групп — Сопротивление' :
    count >= 3 ? 'Спешка · 4 группы — Сила' : '3 группы — Спешка';
  return [{ text: 'Рацион ' + count + '/5', color: count >= 3 ? 'green' : 'gray' }, { text: ' · ' + bonus, color: 'gray' }];
}

// Debt: a heart lost on death comes back for as many points of different dishes as the last stage took.
function avStageSize(points) {
  var m = avStagesBy(points);
  if (m <= 0) return AV_KD_MILESTONES[0];
  return AV_KD_MILESTONES[m - 1] - (m >= 2 ? AV_KD_MILESTONES[m - 2] : 0);
}
function avDebtInit(server, player) {
  var st = avHeartState(server, player);
  if (!st.contains('debt_v')) {
    st.putInt('debt_v', 1);
    var d0 = -st.getInt('delta');
    if (d0 > 0 && st.getInt('debt') < d0) st.putInt('debt', d0);
  }
  if (st.getInt('debt') > 0 && st.getInt('rec_need') <= 0) {
    st.putInt('rec_need', avStageSize(st.getInt('pts')));
    if (!st.contains('rec')) st.put('rec', new AV_KH_CompoundTag());
  }
  return st;
}
// Counts a dish towards the debt. null = no debt, else { have, need, back } (back = a heart came back just now).
function avRecover(server, player, key) {
  var st = avDebtInit(server, player);
  if (st.getInt('debt') <= 0) return null;
  if (avHearts(server, player) >= AV_HEARTS_MAX) { st.putInt('debt', 0); st.putInt('rec_need', 0); st.remove('rec'); return null; }
  if (!st.contains('rec')) st.put('rec', new AV_KH_CompoundTag());
  var rec = st.getCompound('rec');
  if (key) rec.putBoolean(key, true);
  var have = avPointsOf(rec), need = st.getInt('rec_need');
  if (have < need) return { have: have, need: need, back: false };
  st.putInt('debt', st.getInt('debt') - 1);
  st.putInt('delta', st.getInt('delta') + 1);
  st.put('rec', new AV_KH_CompoundTag());
  st.putInt('rec_need', st.getInt('debt') > 0 ? avStageSize(st.getInt('pts')) : 0);
  return { have: have, need: need, back: true };
}
function avDebtText(st) {
  var debt = st.getInt('debt'); if (debt <= 0) return '';
  var have = st.contains('rec') ? avPointsOf(st.getCompound('rec')) : 0;
  return 'возврат сердца ' + have + '/' + st.getInt('rec_need') + ' очков' + (debt > 1 ? ' (ещё сердец к возврату: ' + debt + ')' : '');
}

// Records a new dish for a player. Returns null if it was already known, else { pts, tier, next }.
function avCreditDish(s, player, key, descId, feastFrom) {
  var tasted = avKitchenPlayer(s, player);
  if (tasted.contains(key)) return null;
  var n = player.username;
  var before = avHearts(s, player);
  tasted.putBoolean(key, true);
  var st = avHeartState(s, player);
  var tier = Math.max(1, avDishTier(key));
  var pts = st.getInt('pts') + tier;
  st.putInt('pts', pts);
  s.runCommandSilent('scoreboard players set ' + n + ' av_dishes ' + tasted.getAllKeys().size());
  var after = avHeartsApply(s, player);
  if (after > before) {
    avHeartsTitle(s, n, '+1 сердце', 'red', 'Очков гурмана: ' + pts + ' · сердец: ' + after);
    s.runCommandSilent('execute as ' + n + ' at @s run playsound minecraft:entity.player.levelup master @s ~ ~ ~ 0.8 1.2');
    s.runCommandSilent('tellraw @a ' + JSON.stringify([{ text: n, color: 'yellow' }, { text: ': ' + pts + ' очков гурмана — +1 сердце (' + after + ').', color: 'gold' }]));
  } else if (avStagesBy(pts) > avStagesBy(pts - tier) && before >= AV_HEARTS_MAX) {
    s.runCommandSilent('tellraw ' + n + ' ' + JSON.stringify({ text: pts + ' очков гурмана — но сердец уже ' + AV_HEARTS_MAX + ', это максимум.', color: 'gray' }));
  }
  avRankCheck(s, player);
  if (feastFrom) {
    s.runCommandSilent('title ' + n + ' actionbar ' + JSON.stringify([{ text: 'Общий стол: ', color: 'gold' }, { text: feastFrom + ' угостил: ', color: 'gray' },
      { translate: descId, color: 'yellow' }, { text: ' ' + avStars(tier) + ' +' + tier + ' · очков ' + pts, color: 'gray' }]));
  }
  return { pts: pts, tier: tier, next: avNextMilestone(pts) };
}

// Feast servings count for the eater's guild mates nearby.
const AV_KH_Teams = (function () { try { return Java.loadClass('dev.ftb.mods.ftbteams.api.FTBTeamsAPI'); } catch (x) { return null; } })();
function avFeastShare(s, player, key, descId) {
  if (!AV_KH_Teams) return 0;
  var shared = 0;
  try {
    var opt = AV_KH_Teams.api().getManager().getTeamForPlayer(player);
    if (!opt.isPresent() || !opt.get().isPartyTeam()) return 0;
    var it = opt.get().getMembers().iterator();
    while (it.hasNext()) {
      var mate = s.getPlayerList().getPlayer(it.next());
      if (!mate || String(mate.uuid) === String(player.uuid)) continue;
      if (String(mate.level.dimension) !== String(player.level.dimension) || mate.distanceToSqr(player) > AV_FEAST_RANGE * AV_FEAST_RANGE) continue;
      if (avCreditDish(s, mate, key, descId, player.username)) shared++;
    }
  } catch (x) { console.warn('[avgustov] feast share: ' + x); }
  return shared;
}

ItemEvents.foodEaten(function (e) {
  var player = e.player || (e.entity && e.entity.isPlayer() ? e.entity : null);
  if (!player || !e.server) return;
  var item = e.item;
  var food = null;
  try { food = item.get(AV_DataComponents.FOOD); } catch (x) {}
  if (!food) return;
  var s = e.server;
  var n = player.username;
  var key = String(item.id), descId = String(item.descriptionId);
  var bar = avDiet(s, player, key, avDishGroups(key), true);
  if (food.nutrition() < AV_KITCHEN_MIN_NUTRITION) { s.runCommandSilent('title ' + n + ' actionbar ' + JSON.stringify(bar)); return; }
  var got = avCreditDish(s, player, key, descId, null);
  if (got) {
    bar = [{ text: 'Новое блюдо: ', color: 'gold' }, { translate: descId, color: 'yellow' },
      { text: ' ' + avStars(got.tier) + ' +' + got.tier + ' · очков ' + got.pts + (got.next ? ' · до сердца ' + (got.next - got.pts) : ''), color: 'gray' }];
  }
  if (AV_KD_FEAST[key]) {
    var shared = avFeastShare(s, player, key, descId);
    if (shared > 0) bar = bar.concat([{ text: ' · общий стол: +' + shared, color: 'gold' }]);
  }
  var r = avRecover(s, player, key);
  if (r && r.back) {
    var h2 = avHeartsApply(s, player);
    avHeartsTitle(s, n, '+1 сердце', 'red', 'Сердце вернулось: ' + r.need + ' очков разных блюд · сердец: ' + h2);
    s.runCommandSilent('execute as ' + n + ' at @s run playsound minecraft:entity.player.levelup master @s ~ ~ ~ 0.8 1.2');
  } else if (r) {
    bar = bar.concat([{ text: ' · возврат сердца ' + r.have + '/' + r.need, color: 'light_purple' }]);
  }
  s.runCommandSilent('title ' + n + ' actionbar ' + JSON.stringify(bar));
});

// Drinks without a food component (water, juices, potions) still count for the "drinks" diet group.
NativeEvents.onEvent('net.neoforged.neoforge.event.entity.living.LivingEntityUseItemEvent$Finish', function (e) {
  try {
    var ent = e.getEntity();
    if (!ent || !ent.isPlayer() || ent.level.isClientSide()) return;
    var st = e.getItem();
    if (!st || st.isEmpty() || st.get(AV_DataComponents.FOOD) != null) return;
    if (String(st.getUseAnimation()).toLowerCase() !== 'drink') return;
    var s = ent.getServer();
    if (!s) return;
    var key = String(st.getItem().builtInRegistryHolder().key().location());
    var groups = avDishGroups(key) | 16;
    s.runCommandSilent('title ' + ent.username + ' actionbar ' + JSON.stringify(avDiet(s, ent, key, groups, false)));
  } catch (x) { console.warn('[avgustov] drink diet: ' + x); }
});

// Crystal Heart: +1 heart up to the maximum.
ItemEvents.rightClicked('legendarysurvivaloverhaul:heart_container', function (e) {
  var player = e.player, s = e.server;
  if (!player || !s) return;
  var n = player.username;
  var before = avHearts(s, player);
  if (before >= AV_HEARTS_MAX) {
    s.runCommandSilent('title ' + n + ' actionbar ' + JSON.stringify({ text: 'Сердец уже ' + AV_HEARTS_MAX + ' — это максимум', color: 'gray' }));
    e.cancel();
    return;
  }
  var st = avHeartState(s, player);
  st.putInt('delta', st.getInt('delta') + 1);
  var after = avHeartsApply(s, player);
  if (!player.isCreative()) e.item.shrink(1);
  player.heal(2);
  avHeartsTitle(s, n, '+1 сердце', 'light_purple', 'Кристальное сердце · сердец: ' + after);
  s.runCommandSilent('execute as ' + n + ' at @s run playsound minecraft:block.amethyst_block.resonate master @s ~ ~ ~ 1 1');
  e.cancel();
});

// Death: -1 heart, never below the start; the lost heart becomes a debt (see avRecover).
EntityEvents.death(function (e) {
  var ent = e.entity;
  if (!ent.isPlayer() || !e.server) return;
  var s = e.server;
  var before = avHearts(s, ent);
  if (before <= AV_HEARTS_START) return;
  var st = avDebtInit(s, ent);
  st.putInt('delta', st.getInt('delta') - 1);
  st.putInt('debt', st.getInt('debt') + 1);
  if (st.getInt('rec_need') <= 0) {
    st.putInt('rec_need', avStageSize(st.getInt('pts')));
    st.put('rec', new AV_KH_CompoundTag());
  }
  st.putBoolean('lost_msg', true);
});

PlayerEvents.loggedIn(function (e) {
  avKitchenSync(e.server, e.player);
  avDebtInit(e.server, e.player);
  avHeartsApply(e.server, e.player);
  avRankCheck(e.server, e.player);
});
PlayerEvents.respawned(function (e) {
  var s = e.server, p = e.player;
  var h = avHeartsApply(s, p);
  var fromEnd = false;
  try { fromEnd = e.isEndConquered(); } catch (x) {}
  if (!fromEnd) p.setHealth(h * 2);
  var st = avDebtInit(s, p);
  if (st.getBoolean('lost_msg')) {
    st.remove('lost_msg');
    avHeartsTitle(s, p.username, '−1 сердце', 'dark_red', 'Сердец: ' + h + ' · вернуть: ' + st.getInt('rec_need') + ' очков разных блюд (знакомые тоже) или Кристальное сердце');
  }
});

// "Журнал гурмана": a written book with the progress, the diet and the dishes not tried yet.
const AV_KH_WBC = Java.loadClass('net.minecraft.world.item.component.WrittenBookContent');
const AV_KH_Filterable = Java.loadClass('net.minecraft.server.network.Filterable');
const AV_KH_Component = Java.loadClass('net.minecraft.network.chat.Component');
const AV_KH_ArrayList = Java.loadClass('java.util.ArrayList');
const AV_KH_ItemStack = Java.loadClass('net.minecraft.world.item.ItemStack');
const AV_KH_Items = Java.loadClass('net.minecraft.world.item.Items');
const AV_KH_BuiltIn = Java.loadClass('net.minecraft.core.registries.BuiltInRegistries');
const AV_KH_RL = Java.loadClass('net.minecraft.resources.ResourceLocation');
const AV_JOURNAL_TITLE = 'Журнал гурмана';
function avLit(text) { return AV_KH_Component.literal(text); }
function avJournalPages(s, p) {
  var st = avKitchenSync(s, p), tasted = avKitchenPlayer(s, p);
  var pts = st.getInt('pts'), h = avHearts(s, p), next = avNextMilestone(pts), rank = avRankOf(avStages(s, p));
  var pages = new AV_KH_ArrayList();
  var add = function (c) { pages.add(AV_KH_Filterable.passThrough(c)); };
  var dishes = 0, tried = 0;
  Object.keys(AV_KD).forEach(function (k) { if (AV_KD[k][0] > 0) { dishes++; if (tasted.contains(k)) tried++; } });
  add(avLit('§l' + AV_JOURNAL_TITLE + '§r\n\n' + p.username + '\nЗвание: ' + (rank ? rank.name : '—') + '\n\nСердец: ' + h + ' из ' + AV_HEARTS_MAX +
    '\nОчков: ' + pts + (next ? '\nДо сердца: ' + (next - pts) : '\nВсе сердца за блюда получены') +
    '\n\nБлюд: ' + tried + ' из ' + dishes + (avDebtText(st) ? '\n\n§5' + avDebtText(st) : '')));
  add(avLit('§lОчки§r\nНовое блюдо даёт:\n★ 1 — печь, костёр, 1–2 продукта\n★★ 2 — доска, 3–4 продукта\n★★★ 3 — котелок, машины Create, бочки, пиры\n\n' +
    'Пир засчитывается всей гильдии в ' + AV_FEAST_RANGE + ' блоках.\n\nСердца: ' + AV_KD_MILESTONES.join(', ') + ' очков.'));
  var raw = String(st.getString('diet')), list = raw ? raw.split(',') : [], union = 0;
  list.forEach(function (g) { union |= parseInt(g) || 0; });
  var diet = '§lРацион§r\nПоследние ' + list.length + ' из ' + AV_DIET_LEN + ':\n';
  AV_GROUPS.forEach(function (g) { diet += (union & g.bit ? '§2✔ ' : '§4✘ ') + g.name + '§r\n'; });
  add(avLit(diet + '\n3 группы — Спешка\n4 — и Сила\n5 — и Сопротивление\n10 раз одна группа — Слабость'));
  var groups = {};
  Object.keys(AV_KD).forEach(function (k) {
    var d = AV_KD[k];
    if (!(d[0] > 0) || tasted.contains(k)) return;
    var gi = 0;
    for (var i = 0; i < AV_GROUPS.length; i++) if (d[1] & AV_GROUPS[i].bit) { gi = i; break; }
    (groups[gi] = groups[gi] || []).push(k);
  });
  var budget = 95;
  AV_GROUPS.forEach(function (g, gi) {
    var ids = groups[gi]; if (!ids || budget <= 0) return;
    ids.sort(function (a, b) { return AV_KD[b][0] - AV_KD[a][0] || (a < b ? -1 : 1); });
    for (var off = 0; off < ids.length && budget > 0; off += 7) {
      var page = avLit('§lНе пробовали: ' + g.name + '§r\n');
      ids.slice(off, off + 7).forEach(function (k) {
        var desc = k;
        try { desc = String(AV_KH_BuiltIn.ITEM.get(AV_KH_RL.parse(k)).getDescriptionId()); } catch (x) {}
        page.append(avLit('\n' + avStars(AV_KD[k][0]) + ' ')).append(AV_KH_Component.translatable(desc))
          .append(avLit(' §8(' + (AV_KD_MODS[k.split(':')[0]] || k.split(':')[0]) + (AV_KD_FEAST[k] ? ', пир' : '') + ')§r'));
      });
      add(page); budget--;
    }
  });
  return pages;
}
function avJournalGive(s, p) {
  var stack = new AV_KH_ItemStack(AV_KH_Items.WRITTEN_BOOK);
  stack.set(AV_DataComponents.WRITTEN_BOOK_CONTENT, new AV_KH_WBC(AV_KH_Filterable.passThrough(AV_JOURNAL_TITLE), 'Артель', 0, avJournalPages(s, p), true));
  var inv = p.getInventory();
  for (var i = 0; i < inv.getContainerSize(); i++) {
    var it = inv.getItem(i);
    if (it.isEmpty() || !it.has(AV_DataComponents.WRITTEN_BOOK_CONTENT)) continue;
    var c = it.get(AV_DataComponents.WRITTEN_BOOK_CONTENT);
    if (String(c.title().raw()) === AV_JOURNAL_TITLE && String(c.author()) === 'Артель') { inv.setItem(i, stack); return 'обновлён'; }
  }
  if (!inv.add(stack)) p.drop(stack, false);
  return 'выдан';
}

ServerEvents.commandRegistry(function (e) {
  var Commands = e.commands;
  e.register(Commands.literal('hearts').executes(function (ctx) {
    var p = ctx.source.player;
    if (!p) return 0;
    var s = ctx.source.server;
    var st = avKitchenSync(s, p);
    var pts = st.getInt('pts'), h = avHearts(s, p), next = avNextMilestone(pts), rank = avRankOf(avStages(s, p));
    var debt = avDebtText(avDebtInit(s, p));
    p.tell(Text.of('Сердец: ' + h + ' из ' + AV_HEARTS_MAX + ' · очков гурмана: ' + pts + (next ? ' · следующее сердце на ' + next : '') +
      (rank ? ' · звание «' + rank.name + '»' : '') + (debt ? ' · ' + debt : '') + ' · подробно: /gourmet').gold());
    return 1;
  }));
  e.register(Commands.literal('gourmet').executes(function (ctx) {
    var p = ctx.source.player;
    if (!p) return 0;
    var how = avJournalGive(ctx.source.server, p);
    p.tell(Text.of('Журнал гурмана ' + how + ' — он в инвентаре.').gold());
    return 1;
  }));
});
